fn row(
    event_index: usize,
    turn_id: &str,
    kind: CompactionKind,
    text: &str,
    dedupe_identity: Option<String>,
) -> CompactionRow {
    CompactionRow {
        source_file: Utf8PathBuf::from("/tmp/session-r4-2/rollout.jsonl"),
        source_kind: SourceKind::CodexRolloutJsonl,
        session_id: Some("session-r4-2".to_string()),
